// middleware.js — Pantallas de acceso de «Mi psicóloga en el bolsillo»
//   gracielasalvador.com/bolsillo   → versión general      (contraseña en Vercel: HERRAMIENTAS_PASSWORD)
//   gracielasalvador.com/madreria   → La Madrería          (contraseña en Vercel: MADRERIA_PASSWORD)
// Cada entrada tiene su propia contraseña y su propio acceso recordado: entrar en una no abre la otra.
// Va en la RAÍZ del proyecto (al lado de index.html principal).
// La dirección antigua /herramientas (el «Área de pacientes» del pie de la web) lleva a /pacientes/, donde se elige entre las dos entradas.
// Las contraseñas NO están aquí: se guardan en Vercel como variables de entorno.

export const config = { matcher: ['/bolsillo', '/bolsillo/:path*', '/herramientas', '/herramientas/:path*', '/madreria', '/madreria/:path*'] };

const DIAS = 30; // días que el dispositivo recuerda el acceso

const ESPACIOS = {
  bolsillo: {
    variable: 'HERRAMIENTAS_PASSWORD', cookie: 'gs_acceso', semilla: 'gs-herramientas:',
    logo: '', logoAlt: 'Logo de Graciela Salvador', letras: '',
    titulo: 'Mi psicóloga en el bolsillo', eyebrow: '', marca: '<b>Graciela Salvador</b> · Psicóloga',
    texto: 'Herramientas guiadas para entender lo que sientes y cuidarte, a tu ritmo y siempre a mano. Escribe tu contraseña para entrar.', edicion: '',
    claro: '--bg:#F5F9F9;--surface:#FFFFFF;--ink:#17343B;--muted:#5C747A;--line:#D7E5E8;--accent:#166A7E;--deep:#0F4C5C;--tint:#E4EFF1;--on:#FFFFFF;--err:#8E4E33;--errbg:#F4E3DA',
    oscuro: '--bg:#0C1C21;--surface:#12282E;--ink:#E2EEF0;--muted:#9AB2B8;--line:#234046;--accent:#5FB2C3;--deep:#9AD3DE;--tint:#18343B;--on:#0C1C21;--err:#E8B39A;--errbg:#3A2A23',
    tema: '#0F4C5C',
  },
  madreria: {
    variable: 'MADRERIA_PASSWORD', cookie: 'gs_madreria', semilla: 'gs-madreria:',
    logo: '', logoAlt: 'Logo de La Madrería', letras: '',
    titulo: 'Mi psicóloga en el bolsillo', eyebrow: '', marca: '<b>Graciela Salvador</b> · Maternidad y crianza',
    texto: 'Herramientas guiadas para acompañarte en el embarazo, el posparto y la crianza. Escribe tu contraseña para entrar.', edicion: 'Edición La Madrería',
    claro: '--bg:#FDFDFB;--surface:#FFFFFF;--ink:#16343B;--muted:#5E6F72;--line:#DCE6E8;--accent:#11667D;--deep:#0B4757;--tint:#E3EFF1;--on:#FFFFFF;--err:#8E4E33;--errbg:#F6E3D6;--edc:#B9B20E;--edbg:#F4F2CC;--edink:#11667D',
    oscuro: '--bg:#0D1B1F;--surface:#142629;--ink:#E4EEEF;--muted:#9DB1B5;--line:#26393D;--accent:#5DB4C6;--deep:#A0D5E0;--tint:#183339;--on:#0D1B1F;--err:#E8B39A;--errbg:#3A2A23;--edc:#DCD56A;--edbg:#2E2C12;--edink:#DCD56A',
    tema: '#0B4757',
  },
};

async function huella(semilla, pass) {
  const data = new TextEncoder().encode(semilla + pass);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(hash)].map(b => b.toString(16).padStart(2, '0')).join('');
}

function leerCookie(req, nombre) {
  const c = req.headers.get('cookie') || '';
  const m = c.match(new RegExp('(?:^|;\\s*)' + nombre + '=([^;]+)'));
  return m ? m[1] : null;
}

const continuar = () => new Response(null, { headers: { 'x-middleware-next': '1' } });

export default async function middleware(req) {
  const url = new URL(req.url);
  // «Área de pacientes» (enlace antiguo /herramientas en el pie de la web) → página para elegir entre las dos entradas
  if (url.pathname === '/herramientas' || url.pathname === '/herramientas/') return Response.redirect(new URL('/pacientes/', url), 308);
  if (url.pathname.startsWith('/herramientas/')) return Response.redirect(new URL(url.pathname.replace(/^\/herramientas/, '/bolsillo') + url.search, url), 308);

  const id = url.pathname.split('/')[1];
  const E = ESPACIOS[id];
  if (!E) return continuar();
  const pass = process.env[E.variable];
  if (!pass) return pantalla(E, id, 'Falta configurar la contraseña en Vercel.', 500);
  const valida = await huella(E.semilla, pass);

  if (req.method === 'POST') {
    let escrita = '';
    try { escrita = String((await req.formData()).get('clave') || ''); } catch (e) {}
    if (escrita.trim() === pass) {
      return new Response(null, { status: 303, headers: {
        'Location': `/${id}/`,
        'Set-Cookie': `${E.cookie}=${valida}; Path=/${id}; Max-Age=${DIAS * 86400}; HttpOnly; Secure; SameSite=Lax`,
        'Cache-Control': 'no-store' } });
    }
    return pantalla(E, id, 'La contraseña no es correcta. Revísala o pídesela a Graciela.', 401);
  }

  if (url.pathname === `/${id}`) return Response.redirect(new URL(`/${id}/` + url.search, url), 308);
  if (leerCookie(req, E.cookie) === valida) return continuar();
  return pantalla(E, id, '', 401);
}

function pantalla(E, id, error, status) {
  const html = `<!doctype html><html lang="es"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex"><meta name="theme-color" content="${E.tema}">
<title>${E.titulo}${E.edicion ? ' · ' + E.edicion : ''} · Acceso</title>
<link rel="icon" type="image/png" href="data:image/png;base64,${E.logo}">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,500;1,500&family=Nunito+Sans:opsz,wght@6..12,400;6..12,700&display=swap">
<style>
:root{${E.claro}}
@media (prefers-color-scheme:dark){:root{${E.oscuro};color-scheme:dark}}
*{box-sizing:border-box}html,body{margin:0;height:100%}
body{background:var(--bg);color:var(--ink);font-family:"Nunito Sans","Segoe UI",system-ui,sans-serif;display:grid;place-items:center;
 padding:24px max(16px,env(safe-area-inset-right,0px)) 24px max(16px,env(safe-area-inset-left,0px))}
main{width:100%;max-width:380px;background:var(--surface);border:1px solid var(--line);border-radius:26px;padding:32px 24px;display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center}
.logo{width:76px;height:76px;border-radius:50%;background:#fff;display:grid;place-items:center;border:1px solid var(--line)}.logo img{width:60px}
.brand{font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}.brand b{color:var(--deep)}
.eyebrow{font-size:.74rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent);margin:6px 0 -10px}
h1{font-family:Lora,Georgia,serif;font-weight:500;color:var(--deep);font-size:1.7rem;margin:4px 0 0}
p{margin:0;color:var(--muted);line-height:1.5}
form{width:100%;display:flex;flex-direction:column;gap:10px;margin-top:6px}
input{width:100%;font:inherit;font-size:1.05rem;padding:14px;border-radius:14px;border:1.5px solid var(--line);background:var(--bg);color:var(--ink);text-align:center}
input:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
button{font:inherit;font-weight:700;font-size:1rem;border:0;border-radius:999px;padding:13px;background:var(--accent);color:var(--on);cursor:pointer}
.ed{display:inline-flex;align-items:center;gap:6px;font-size:.74rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;background:var(--edbg);color:var(--edink);padding:5px 12px;border-radius:999px;margin-top:-4px}.ed i{width:8px;height:8px;border-radius:50%;background:var(--edc)}
main.edi{position:relative;overflow:hidden;border-color:color-mix(in srgb,var(--edc) 45%,var(--line))}main.edi::before{content:'';position:absolute;left:0;right:0;top:0;height:6px;background:var(--edc)}
.err{background:var(--errbg);color:var(--err);border-radius:12px;padding:10px 12px;font-size:.92rem;width:100%}
small{color:var(--muted);font-size:.82rem;line-height:1.45}
h1.wm{margin:6px 0 2px;line-height:0}h1.wm img{width:200px;max-width:80%}
@media (prefers-color-scheme:dark){h1.wm img{filter:brightness(0) invert(1) opacity(.88)}}
</style></head><body><main${E.edicion ? ' class="edi"' : ''}>
<div class="logo"><img src="data:image/png;base64,${E.logo}" alt="${E.logoAlt}"></div>
<div class="brand">${E.marca}</div>
${E.eyebrow ? `<p class="eyebrow">${E.eyebrow}</p>` : ''}
${E.letras ? `<h1 class="wm"><img src="data:image/png;base64,${E.letras}" alt="${E.titulo}"></h1>` : `<h1>${E.titulo}</h1>`}
${E.edicion ? `<span class="ed"><i></i>${E.edicion}</span>` : ''}
<p>${E.texto}</p>
${error ? `<div class="err" role="alert">${error}</div>` : ''}
<form method="post" action="/${id}/">
<label for="clave" style="position:absolute;left:-9999px">Contraseña</label>
<input id="clave" name="clave" type="password" autocomplete="current-password" placeholder="Contraseña" required autofocus>
<button type="submit">Entrar</button>
</form>
<small>Este dispositivo recordará el acceso durante ${DIAS} días.</small>
</main></body></html>`;
  return new Response(html, { status, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
}
